import json
p='[REDACTED LOCAL PATH]'
d=json.load(open(p))
# recursively find field path genomeDir options
def walk(o,path=''):
    if isinstance(o,dict):
        if o.get('name')=='genomeDir' or (o.get('type')=='select' and 'genome' in str(o.get('label','')).lower() and 'reference' in str(o.get('label','')).lower()):
            opts=o.get('options') or []
            if opts:
                print('PATH',path,'label',o.get('label'),'count',len(opts))
                for x in opts:
                    label=x if isinstance(x,str) else x.get('label') or x.get('value')
                    value=x.get('value') if isinstance(x,dict) else x
                    s=str(label)+' '+str(value)
                    if any(k in s for k in ['human','hg38','hg19','GRCh38','GRCh37','Homo']):
                        print(' ',label,'=>',value)
        for k,v in o.items():
            if isinstance(v,dict): walk(v,path+'/'+k)
            elif isinstance(v,list):
                for i,x in enumerate(v): walk(x,path+'/'+k+'/'+str(i))
walk(d)
PY"

