    if isinstance(o,dict):
        if o.get('name')=='files' or o.get('type')=='upload_dataset':
            print('PATH',path)
            print(json.dumps(o,indent=2)[:5000])
        for k,v in o.items():
            if isinstance(v,dict): walk(v,path+'/'+k)
            elif isinstance(v,list):
                for i,x in enumerate(v): walk(x,path+'/'+k+'/'+str(i))
walk(inp)
PY"

